import{_ as n,o as s,c as e,a2 as l}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"Hazard Pointer","description":"","frontmatter":{},"headers":[],"relativePath":"notes/linux-kernel/concurrency/hazard_pointer.md","filePath":"notes/linux-kernel/concurrency/hazard_pointer.md"}'),p={name:"notes/linux-kernel/concurrency/hazard_pointer.md"};function i(r,a,t,o,c,d){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="hazard-pointer" tabindex="-1">Hazard Pointer <a class="header-anchor" href="#hazard-pointer" aria-label="Permalink to &quot;Hazard Pointer&quot;">​</a></h1><p>与 RCU 类似，hazard pointer 用于在对象可能被释放时持有其短期引用。RCU 保护的代码必须禁用抢占，而 hazard pointer 的设计则允许抢占，尽管这种用法未必最优。</p><h2 id="linux-内核-hazard-pointer-提案概述" tabindex="-1">Linux 内核 Hazard Pointer 提案概述 <a class="header-anchor" href="#linux-内核-hazard-pointer-提案概述" aria-label="Permalink to &quot;Linux 内核 Hazard Pointer 提案概述&quot;">​</a></h2><blockquote><p>本文总结 LWN.net 文章《Hazard pointers for the kernel》所讨论的 Linux 内核 Hazard Pointer 提案。该方案旨在补充 RCU、SRCU 和引用计数等现有对象生命周期管理机制。目前相关补丁仍处于 RFC 阶段，并非稳定内核接口。</p></blockquote><h2 id="_1-要解决的问题" tabindex="-1">1. 要解决的问题 <a class="header-anchor" href="#_1-要解决的问题" aria-label="Permalink to &quot;1. 要解决的问题&quot;">​</a></h2><p>无锁数据结构的读者通常先读取一个共享指针，再访问它所指向的对象：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">obj </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> shared_ptr;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(obj);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>问题在于，更新者可能在这两步之间将对象从数据结构中删除并释放。读者随后继续访问 <code>obj</code> 时，就会产生 use-after-free。</p><p>传统引用计数要求读者增加对象引用，但“读取对象指针”和“增加引用计数”本身并非一个不可分割的操作：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读者读取 obj</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>更新者删除并释放 obj</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>读者尝试增加 obj 的引用计数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>此时引用计数已经位于被释放的内存中。因此，仅调用 <code>refcount_inc()</code> 并不能自动解决无锁查找与对象销毁之间的竞态。</p><p>RCU 可以解决这一问题。更新者先从共享数据结构中移除对象，再等待一个 grace period，确认旧读者全部离开临界区后才释放对象。RCU 的读侧开销很低，但对象回收可能被较长的宽限期延迟；当大量待回收对象积压时，还可能造成较高的内存占用。</p><h2 id="_2-hazard-pointer-的基本思想" tabindex="-1">2. Hazard Pointer 的基本思想 <a class="header-anchor" href="#_2-hazard-pointer-的基本思想" aria-label="Permalink to &quot;2. Hazard Pointer 的基本思想&quot;">​</a></h2><p>Hazard Pointer 让每个读者公开声明：</p><blockquote><p>我当前正在使用这个对象，在该声明撤销之前不要释放它。</p></blockquote><p>读者的大致操作流程如下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读取共享指针 P</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>将 P 发布到自己的 hazard slot</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>重新读取共享指针</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>如果共享指针已改变，则重试</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>安全访问 P</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>清除 hazard slot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>发布 hazard pointer 后必须重新读取共享指针，因为对象可能在“第一次读取”和“发布 hazard pointer”之间被更新者移除。只有在发布后重新检查共享指针仍然指向同一对象，读者才能确认该对象在保护建立之前没有失效。</p><p>更新者的大致流程如下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从共享数据结构中移除对象 P</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>扫描所有 hazard slot</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>如果仍有 slot 指向 P，则暂缓释放</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>如果没有 slot 指向 P，则释放对象</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>因此，Hazard Pointer 将“谁仍可能访问对象”从 RCU 的隐式临界区，转换为可枚举的显式指针集合。</p><h2 id="_3-hazard-pointer-与-rcu-的核心差异" tabindex="-1">3. Hazard Pointer 与 RCU 的核心差异 <a class="header-anchor" href="#_3-hazard-pointer-与-rcu-的核心差异" aria-label="Permalink to &quot;3. Hazard Pointer 与 RCU 的核心差异&quot;">​</a></h2><p>两者都允许读者在更新并发发生时继续访问旧对象，但判断对象是否可以释放的方法不同：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RCU：</span></span>
<span class="line"><span>等待所有旧读者经过 quiescent state，</span></span>
<span class="line"><span>然后认为旧对象不再被访问。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hazard Pointer：</span></span>
<span class="line"><span>检查所有读者公开的 hazard slot，</span></span>
<span class="line"><span>确认没有 slot 指向待回收对象。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>RCU 的回收时间取决于 grace period。某个迟迟不经过静止状态的 CPU、任务或虚拟 CPU，可能延迟一批对象的回收。Hazard Pointer 只保护读者明确发布的对象，因此可以更有针对性地判断某个对象是否能够释放。</p><p>Hazard Pointer 也并非没有代价：</p><ul><li>读者必须发布 hazard slot；</li><li>读者必须执行必要的内存顺序操作；</li><li>发布后需要重新验证共享指针；</li><li>更新者或回收者必须扫描 slot；</li><li>内核还必须管理抢占、迁移和不同执行上下文中的 slot 生命周期。</li></ul><p>因此，对于持续时间短、数量巨大且不允许阻塞的读侧临界区，普通 RCU 通常仍然更合适。</p><h2 id="_4-为什么内核实现比较复杂" tabindex="-1">4. 为什么内核实现比较复杂 <a class="header-anchor" href="#_4-为什么内核实现比较复杂" aria-label="Permalink to &quot;4. 为什么内核实现比较复杂&quot;">​</a></h2><p>用户空间的 Hazard Pointer 通常将 slot 绑定到线程，但 Linux 内核中的执行上下文更加复杂：</p><ul><li>任务可能被抢占并迁移到其他 CPU；</li><li>读者可能睡眠或长期阻塞；</li><li>获取与释放可能发生在不同执行上下文；</li><li>中断处理程序也可能使用 hazard pointer；</li><li>hazard context 可能分配在栈上；</li><li>CPU 热插拔和任务退出不能留下失效 slot；</li><li>模块卸载前必须确认相关异步回收已经完成。</li></ul><p>当前 RFC 方案为每个 CPU 提供预分配 slot，并在这些 slot 不足时退回到备用 slot。为了处理抢占和任务迁移，当任务发生上下文切换时，仍在使用的 per-CPU hazard pointer 需要迁移到与具体 context 关联的备用位置，以避免被抢占任务长期占用或错误引用某个 CPU 的 slot。</p><p>RFC v2 还增加了 <code>hazptr_detach()</code>，允许 hazard pointer 的 acquire 和 release 发生在不同执行上下文。例如，一个任务建立保护后，可以将释放工作交给另一个任务或 IPI handler。在 detach 过程中，保护状态从 per-CPU slot 转移到 context 的备用 slot，并依靠 acquire/release 内存顺序保证回收扫描不会在迁移窗口中遗漏该指针。</p><h2 id="_5-当前补丁系列的主要内容" tabindex="-1">5. 当前补丁系列的主要内容 <a class="header-anchor" href="#_5-当前补丁系列的主要内容" aria-label="Permalink to &quot;5. 当前补丁系列的主要内容&quot;">​</a></h2><p>截至 2026 年 7 月 15 日，Paul McKenney 发布的 RFC v2 包含 24 个补丁，主要涉及：</p><ul><li>Hazard Pointer 基础实现；</li><li><code>refscale</code> 性能测试；</li><li>独立的 <code>hazptrtorture</code> 压力测试；</li><li>栈上 <code>hazptr_ctx</code> 测试；</li><li>读者睡眠、CPU 超额配置和上下文迁移测试；</li><li>中断上下文中的 acquire 和 release；</li><li>延迟释放和跨 CPU 释放；</li><li><code>hazptr_detach()</code>；</li><li><code>CONFIG_HAZPTR_DEBUG</code> 误用检测；</li><li>ownership 问题修复；</li><li>内核文档和测试参数。</li></ul><p>该系列中相当一部分内容用于 torture testing，而不是核心 API 本身。这表明当前评审重点已经从“接口能否工作”转向以下正确性问题：</p><ul><li>抢占后保护是否仍然有效；</li><li>任务迁移时 slot 是否安全；</li><li>中断上下文能否正确建立和解除保护；</li><li>acquire 与 release 跨上下文时所有权是否明确；</li><li>错误使用能否被调试配置检测；</li><li>极端并发下是否可能提前释放对象。</li></ul><h2 id="_6-可能适合的场景" tabindex="-1">6. 可能适合的场景 <a class="header-anchor" href="#_6-可能适合的场景" aria-label="Permalink to &quot;6. 可能适合的场景&quot;">​</a></h2><p>Hazard Pointer 更适合同时具有以下特征的场景：</p><ol><li>读路径需要良好的多核可扩展性；</li><li>不能为每次访问都争用共享引用计数缓存行；</li><li>读者保护时间可能没有明确上限；</li><li>读者可能睡眠或跨越调度；</li><li>对象需要比 RCU grace period 更及时地回收；</li><li>每个读者同时保护的对象数量较少。</li></ol><p>早期 RFC 将 Hazard Pointer 概括为一种具有 RCU 式 API 的可扩展引用保护机制，并给出了较好的读侧微基准结果。但这些结果依赖具体硬件、配置和负载，不能直接推导出 Hazard Pointer 在所有实际场景中都优于 RCU。</p><h2 id="_7-与现有机制的定位对比" tabindex="-1">7. 与现有机制的定位对比 <a class="header-anchor" href="#_7-与现有机制的定位对比" aria-label="Permalink to &quot;7. 与现有机制的定位对比&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>refcount：</span></span>
<span class="line"><span>适合表达显式所有权，但共享计数器可能产生缓存行争用；</span></span>
<span class="line"><span>无锁获取引用还可能遇到对象已先被释放的问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RCU：</span></span>
<span class="line"><span>读侧开销很低，但对象回收必须等待 grace period；</span></span>
<span class="line"><span>读者必须遵守相应的临界区规则。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SRCU：</span></span>
<span class="line"><span>允许更灵活的读侧行为，但仍以宽限期为核心。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hazard Pointer：</span></span>
<span class="line"><span>读者显式公布正在访问的对象；</span></span>
<span class="line"><span>回收者可以针对具体对象判断其是否可释放；</span></span>
<span class="line"><span>代价是读侧发布、slot 扫描和执行上下文管理更加复杂。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>Hazard Pointer 的目标不是成为“更快的 RCU”，而是补齐引用计数、RCU 和 SRCU 之间的适用空白。它更可能作为一种有针对性的补充机制，而不是内核中通用的默认对象回收方案。</p><h2 id="_8-当前状态与阅读时的注意事项" tabindex="-1">8. 当前状态与阅读时的注意事项 <a class="header-anchor" href="#_8-当前状态与阅读时的注意事项" aria-label="Permalink to &quot;8. 当前状态与阅读时的注意事项&quot;">​</a></h2><p>相关补丁仍标记为 RFC，说明接口、实现和正确性模型仍处于讨论与验证阶段。当前方案涉及调度器、per-CPU 状态、内存顺序、跨上下文所有权和测试基础设施，而且补丁系列仍在修复 ownership 等问题。</p><p>因此，阅读该文章和补丁时应区分：</p><ul><li>Hazard Pointer 的一般算法原理；</li><li>当前 RFC 提出的 Linux 内核实现；</li><li>邮件讨论中的备选方案；</li><li>已经通过测试的行为；</li><li>尚未进入主线的实验性接口。</li></ul><p>不能将 RFC 中的 API 或实现细节直接视为当前稳定内核的既定行为。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>RCU 通过等待旧读者全部结束来保证对象安全回收，而 Hazard Pointer 让读者显式公布自己正在使用的对象，使回收者能够更精确、更及时地判断某个对象是否可以释放。</p><p>这种机制可能适合读者可阻塞、保护时长无明确上限且对象需要及时回收的场景，但它将复杂度转移到了 slot 管理、内存顺序、任务迁移、跨上下文释放和回收扫描上。当前 Linux 内核实现仍处于 RFC 阶段，开发者正在重点验证抢占、中断、迁移、ownership 和 torture testing 等正确性问题。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>LWN.net, <em>Hazard pointers for the kernel</em>: <a href="https://lwn.net/Articles/1084015/" target="_blank" rel="noreferrer">https://lwn.net/Articles/1084015/</a></li><li>RFC v2, <em>Simple hazard-pointer implementation and torture tests</em>: <a href="https://lwn.net/Articles/1083227/" target="_blank" rel="noreferrer">https://lwn.net/Articles/1083227/</a></li><li>早期 RFC, <em>Add hazard pointers to kernel</em>: <a href="https://lkml.org/lkml/2024/9/17/602" target="_blank" rel="noreferrer">https://lkml.org/lkml/2024/9/17/602</a></li></ul>`,55)])])}const u=n(p,[["render",i]]);export{b as __pageData,u as default};
